<template>
    <div class="container">
        <h1>Formulario estudiante</h1>
        <form id="student-form" @submit.prevent="guardar">
            <div class="form-group">
                <label for="codigo">Código</label>
                <input type="text" id=codigo name="codigo" required v-model="codigo">
            </div>
            <div class="form-group">
                <label for="nombre">Nombre</label>
                <input type="text" id=nombre name="nombre" required v-model="nombre">
            </div>
            <div class="form-group">
                <label for="apellido">Apellido</label>
                <input type="text" id=apellido name="apellido" required v-model="apellido">
            </div>
            <div class="form-group">
                <label for="edad">Edad</label>
                <input type="number" id=edad name="edad" required v-model="edad">
            </div>

            <button type="submit" id="guardar" name="guardar">Guardar</button><br>
            <button type="button" id="eliminar" name="eliminar" @click="eliminar">Eliminar</button><br>
            <button type="button" id="actualizar" name="actualizar" @click="actualizar">Actualizar</button><br>
            <button type="button" id="consultar" name="consultar" @click="consultar">Consultar</button><br>
        </form>

    </div>
</template>

<script>
 import axios from 'axios';

 export default{
    data(){
        return{
            codigo:"",
            nombre:"",
            apellido:"",
            edad:null,
        };
    },
    methods: {
        guardar(){
            axios.post("https://ejemplo318668x2-production.up.railway.app/api/estudiantes",{
                codigo: this.codigo,
                nombre: this.nombre,
                apellido: this.apellido,
                edad: this.edad
            })
            .then((Response) => {
                console.log("Estudiante registrado con éxito", Response.data);
                alert("éxito");
                this.codigo='';
                this.nombre='';
                this.apellido='';
                this.edad='';

            })
            .catch((error) => {
                console.error("Error al registrar el estudiante", error);
            })
        },
        consultar(){
            axios.get("https://ejemplo318668x2-production.up.railway.app/api/estudiantes/"+this.codigo)
            .then((Response) => {
                this.nombre = Response.data.nombre;
                this.apellido = Response.data.apellido;
                this.edad = Response.data.edad;
            })
            .catch((error) =>{
                console.error("Error al consultar el estudiante", error);
            }); 
        },

        actualizar(){
            axios
            .put("https://ejemplo318668x2-production.up.railway.app/api/estudiantes/actualizar/"+this.codigo,{
                codigo: this.codigo,
                nombre: this.nombre,
                apellido: this.apellido,
                edad: this.edad
            })
            .then((Response)=>{
                console.log("Estudiante actualizado con éxito", Response.data);
                this.codigo='';
                this.nombre='';
                this.apellido='';
                this.edad='';
            })
            .catch((error) =>{
                console.log("Error al actualizar", error);
            })
        },

        eliminar(){
            axios
            .delete("https://ejemplo318668x2-production.up.railway.app/api/estudiantes/"+this.codigo)
            .then(() => {
                console.log("Estudiante eliminado con éxito", Response.data);
                this.codigo='';
                this.nombre='';
                this.apellido='';
                this.edad='';
            })
            .catch((error) =>{
                console.log("Error al eliminar", error);
            })
        }        


    }

 }

</script>