<template>
    <div class="container">
        <h1>Tabla de estudiantes</h1>
        <table>
            <thead>
                <tr>
                    <th>Código</th>
                    <th>Nombre</th>
                    <th>Apellido</th>
                    <th>Edad</th>
                </tr>
            </thead>
            <tbody>
                <tr v-for="estudiante in estudiantes" :key="estudiante.codigo">
                    <th>{{ estudiante.codigo }}</th>
                    <th>{{ estudiante.nombre }}</th>
                    <th>{{ estudiante.apellido }}</th>
                    <th>{{ estudiante.edad }}</th>
                </tr>
                
            </tbody>
        </table>
    </div>
</template>

<script>
import axios from 'axios';

export default{
    data(){
        return{
            estudiantes: [],
        };
    },
    methods:{
        obtenerEstudiantes(){
            axios.get("https://ejemplo318668x2-production.up.railway.app/api/estudiantes/listar")
            .then((Response) =>{
                this.estudiantes = Response.data;
            })
            .catch((error) =>{
                console.error("Error al consultar los estudiantes", error);
            })
        }

    },
    mounted(){
        this.obtenerEstudiantes();
    }

}

</script>